#include <iostream>
#include <string>

class ResourceHolder {
public:
    explicit ResourceHolder(const std::string& name)
        : resourceName(name) {
        std::cout << "Acquiring " << resourceName << std::endl;
    }

    ~ResourceHolder() {
        std::cout << "Releasing " << resourceName << std::endl;
    }

private:
    std::string resourceName;
};

int main() {
    std::cout << "Entering main scope" << std::endl;
    {
        ResourceHolder localRes("LocalResourceA");
        std::cout << "Using resource inside block" << std::endl;
    }
    std::cout << "Exited block scope" << std::endl;
    return 0;
}

#include <iostream>
#include <string>

class Tracer {
public:
    Tracer(int id, const std::string& msg)
        : objectID(id), message(msg) {
        std::cout << "Object " << objectID << " constructor runs " << message << std::endl;
    }

    ~Tracer() {
        std::cout << "Object " << objectID << " destructor runs  " << message << std::endl;
    }

private:
    int objectID;
    std::string message;
};

Tracer globalObj(1, "(global before main)");

void create() {
    std::cout << "\nCREATE FUNCTION: EXECUTION BEGINS" << std::endl;
    Tracer fifth(5, "(local automatic in create)");
    static Tracer sixth(6, "(local static in create)");
    Tracer seventh(7, "(local automatic in create)");
    std::cout << "CREATE FUNCTION: EXECUTION ENDS" << std::endl;
}

int main() {
    std::cout << "\nMAIN FUNCTION: EXECUTION BEGINS" << std::endl;
    Tracer second(2, "(local automatic in main)");
    static Tracer third(3, "(local static in main)");

    create();

    std::cout << "\nMAIN FUNCTION: EXECUTION RESUMES" << std::endl;
    Tracer fourth(4, "(local automatic in main)");

    std::cout << "\nMAIN FUNCTION: EXECUTION ENDS" << std::endl;
    return 0;
}
